       "exact_text": "# scrub_v2.bs - Demo A, step 4, option scrub_bowl: fixed program written by the team, not by the model.\n# Version 2 (19/10/2026 evening, Codex Q8): scrub_v1.bs with one change in the pick block: a second pick\n# needs a NEW usable detection of the sponge (observed, this_view, a later pose_step than the refused\n# try's), else the program stops with help(kind=\"cannot_continue\"); a refused pick is never made again on\n# the same detection (pick_pose_uncertain included). Nothing else changed.\n# Look at the region of the sponge the robot tracks and observe, pick it (no yaw: the robot sets the finger\n# axis), take the bowl on the landing tray from the robot's own tracks, scrub 3 s at 4 N, then done().\n# No give_up(): every failure ends with a help of a kind the robot never reviews (cannot_continue, or safety\n# after a contact). No drawer is closed; a drawer of the sponge believed closed is opened again first.\n# Simulation, simulated perception.\n\ndef is_incident(reason):\n    code = str(reason)\n    return code.startswith([\"pull_\", \"push_\"]) or code in [\"stuck\", \"blocked\", \"collision\", \"force_limit\", \"collision_on_approach\", \"lift_blocked\"]\n\ndef is_grip_event(reason):\n    return str(reason) in [\"dropped\", \"slipped\"]\n\ndef region_known(region):\n    if region is None:\n        return False\n    code = str(region)\n    return code.startswith(\"drawer_unit:\") or code in [\"sink_basin\", \"landing_tray\", \"drying_mat\"]\n\ndef fresh_sponge():\n    best = None\n    best_step = -1\n    for t in tracks(\"sponge\"):\n        if t[\"status\"] == \"observed\" and get(t, \"pose_source\") == \"this_view\":\n            step = get(t, \"pose_step\")\n            if step is None:\n                step = 0\n            if best is None or step > best_step:\n                best = t\n                best_step = step\n    return best\n\ndef tray_bowl():\n    best = None\n    best_d = 99.0\n    b0 = base_xy()\n    for b in tracks(\"bowl\"):\n        if b[\"region\"] == \"landing_tray\" and b[\"status\"] != \"held\":\n            dd = hypot(b[\"position_m\"][0] - b0[0], b[\"position_m\"][1] - b0[1])\n            if dd < best_d:\n                best_d = dd\n                best = b\n    return best\n\nif holding():\n    help(\"hand already holds something\", kind=\"cannot_continue\")\ntarget = None\nfor t in tracks(\"sponge\"):\n    if t[\"status\"] == \"observed\" and target is None:\n        target = t\nfor t in tracks(\"sponge\"):\n    if t[\"status\"] == \"stale\" and target is None:\n        target = t\nif target is None:\n    help(\"no sponge track to pick\", kind=\"cannot_continue\")\nregion = target[\"region\"]\nlog(\"demoA.scrub_target\", {\"track_id\": target[\"track_id\"], \"status\": target[\"status\"], \"region\": region})\n\n# ---- the sponge's drawer stays open (D7); one believed closed is opened again before the look\nif region_known(region) and str(region).startswith(\"drawer_unit:\"):\n    h = handle_for_region(region)\n    if h is None:\n        o = observe(\"robot_eye\")\n        h = handle_for_region(region)\n    if h is not None and h[\"opening_m\"] is not None and h[\"opening_m\"] < 0.15:\n        r = open_drawer(h[\"position_m\"], h[\"pull_dir\"])\n        if not r[\"ok\"] and is_incident(r[\"reason\"]):\n            help(\"drawer \" + str(r[\"reason\"]), kind=\"safety\")\n        if not r[\"ok\"]:\n            help(\"drawer \" + str(r[\"reason\"]), kind=\"cannot_continue\")\n\n# ---- a view from above, taken after the last action that could move the sponge (PICK PRECONDITION)\nif region_known(region):\n    r = look_at_region(region)\nelse:\n    p = target[\"position_m\"]\n    r = look_down_at([p[0], p[1]], p[2] - 0.02, 0.42)\nif not r[\"ok\"] and is_incident(r[\"reason\"]):\n    help(\"look \" + str(r[\"reason\"]), kind=\"safety\")\nif r[\"ok\"]:\n    o = observe(\"wrist_cam\")\n\n# ---- pick: at most two tries, each at the newest detection; never the same pick again after a refusal\n# that a new view cannot change (under the unit top, overhead obstruction). v2: a second try only on a\n# detection newer than the refused one (a new view saw the sponge again); otherwise no second pick, help\nheld = False\ntries = 0\nlast = \"no_fresh_detection\"\nused_step = -1\nwhile tries < 2 and not held:\n    sp = fresh_sponge()\n    if sp is None:\n        break\n    step = get(sp, \"pose_step\")\n    if step is None:\n        step = 0\n    if step <= used_step:\n        log(\"demoA.pick_not_retried\", {\"after\": last, \"pose_step\": step})\n        break\n    tries += 1\n    used_step = step\n    r = pick(sp[\"position_m\"], \"sponge\")\n    if r[\"ok\"]:\n        held = True\n    else:\n        last = str(r[\"reason\"])\n        log(\"demoA.pick_not_done\", {\"try\": tries, \"reason\": last})\n        if is_incident(last):\n            help(\"pick \" + last, kind=\"safety\")\n        if is_grip_event(last):\n            help(\"sponge dropped\", kind=\"cannot_continue\")\n        if last in [\"pick_under_unit_top\", \"pick_overhead_obstruction\"]:\n            help(\"pick \" + last, kind=\"cannot_continue\")\n        p = sp[\"position_m\"]\n        r2 = look_down_at([p[0], p[1]], p[2] - 0.02, 0.42)\n        if not r2[\"ok\"] and is_incident(r2[\"reason\"]):\n            help(\"look \" + str(r2[\"reason\"]), kind=\"safety\")\n        if r2[\"ok\"]:\n            o = observe(\"wrist_cam\")\nif not held:\n    help(\"pick failed \" + last, kind=\"cannot_continue\")\nif not holding():\n    help(\"sponge not held after pick\", kind=\"cannot_continue\")\n\n# ---- the bowl on the landing tray: the robot's own track nearest its base (robot_eye if none yet)\nbowl = tray_bowl()\nif bowl is None:\n    o = observe(\"robot_eye\")\n    bowl = tray_bowl()\nif bowl is None:\n    help(\"bowl not seen on the landing tray\", kind=\"cannot_continue\")\ntop = vadd(bowl[\"position_m\"], [0.0, 0.0, 0.023])\nr = scrub(top, 3.0, 4.0)\nif r[\"ok\"]:\n    done()\nlast = str(r[\"reason\"])\nif is_incident(last):\n    help(\"scrub \" + last, kind=\"safety\")\nif is_grip_event(last):\n    help(\"sponge dropped\", kind=\"cannot_continue\")\nhelp(\"scrub \" + last, kind=\"cannot_continue\")"
